import * as C from './civic-engine.mjs';
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(txt,action,id)=>`<button class="btn light" data-action="${action}" data-id="${e(id)}">${e(txt)}</button>`;
export function civicPage(s,name='Camille'){
 const active=C.getCase(s.active)||C.cases[0],d=s.dossiers[active.id],st=C.readStatus(s,active.id),out=C.outcome(s,active.id),p=C.allProgress(s);
 const cards=C.cases.map(c=>`<button class="civic-switch ${c.id===active.id?'current':''}" data-action="civic-case" data-id="${c.id}">${e(c.title)} ${C.readStatus(s,c.id).completed?'✓':''}</button>`).join('');
 const docs=active.facts.map(f=>{const open=d.openDoc===f.id,selected=d.evidence[f.id],ok=selected===f.correct;return `<article class="civic-card"><button class="civic-title" data-action="civic-doc" data-id="${active.id}:${f.id}" aria-expanded="${open}">${e(f.title)} <span>${ok?'✓':open?'−':'+'}</span></button>${open?`<div class="civic-inside"><small>${e(f.sender)}</small><p>${e(f.body)}</p><strong>${e(f.question)}</strong><div class="civic-options">${f.options.map(o=>button(o.text,'civic-fact',active.id+':'+f.id+':'+o.id)).join('')}</div>${selected?`<p class="civic-feedback">${ok?'✓ '+e(f.explain):'Ce choix ne correspond pas à la pièce. Relisez le document.'}</p>`:''}</div>`:''}</article>`}).join('');
 const talks=active.dialogues.map(t=>{const selected=d.dialogue[t.id],picked=t.choices.find(x=>x.id===selected);return `<article class="civic-card"><h3>${e(t.name)}</h3><small>${e(t.role)}</small><p>${e(t.opening)}</p><div class="civic-options">${t.choices.map(o=>button(o.text,'civic-talk',active.id+':'+t.id+':'+o.id)).join('')}</div>${picked?`<p class="civic-feedback">${e(picked.reply)}</p>`:''}</article>`}).join('');
 const decisions=active.decisions.map(a=>`<article class="civic-card ${d.decision===a.id?'chosen':''}"><h3>${e(a.name)}</h3><p>${e(a.detail)}</p>${button(d.decision===a.id?'Option retenue':'Retenir cette option','civic-decision',active.id+':'+a.id)}</article>`).join('');
 return `<section class="civic-world"><div class="civic-hero"><img src="./assets/${active.image}" alt="${e(active.heroAlt)}"><div><span>VALRIVIÈRE · DOSSIERS VIVANTS · ACTE I</span><h1>${e(active.title)}</h1><p>${e(active.subtitle)}</p></div></div><div class="wrapper civic-wrap"><p><strong>Trois dossiers d'institutions</strong> · ${p.completed}/${p.total} validés</p><nav class="civic-switches" aria-label="Choisir le dossier">${cards}</nav><h2>${e(active.objective)}</h2><p>${e(active.lead)}</p><div class="civic-stats"><strong>${st.facts}/${st.totals.facts} faits</strong><strong>${st.talks}/${st.totals.dialogues} dialogues</strong><strong>${st.decision?'Option choisie':'Décision à prendre'}</strong></div><h2>1. Examiner les pièces</h2><div class="civic-grid">${docs}</div><h2>2. Dialoguer</h2><div class="civic-grid">${talks}</div><h2>3. Préparer votre recommandation</h2><div class="civic-grid">${decisions}</div><div class="civic-conclusion">${st.completed?`<h2>Dossier présenté à Marianne</h2><p>${e(out)}</p>${button('Exporter la note TXT','civic-export',active.id)}`:`<p>${st.ready?'Le dossier est prêt pour la DGS.':'Examiner les pièces, comprendre les faits, dialoguer et choisir une option.'}</p>${st.ready?button('Présenter à la DGS','civic-finish',active.id):''}`}</div><h3>Références officielles</h3><div class="civic-links">${active.sources.map(x=>`<a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.label)}</a>`).join('')}</div><p class="fine">Exercices fictifs. Vérifier les textes en vigueur pour tout dossier réel.</p></div></section>`;
}
